namespace Payments;

public interface IPaymentProvider
{
    Task<string> SubmitChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<string> SubmitRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount exceeds maximum.");

        try
        {
            var chargeId = await _provider.SubmitChargeAsync(cardToken, amount, cancellationToken);
            return new ChargeResult(chargeId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception)
        {
            return new ChargeResult(ChargeId: string.Empty, Success: false);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        try
        {
            var refundId = await _provider.SubmitRefundAsync(chargeId, cancellationToken);
            return new RefundResult(refundId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception)
        {
            return new RefundResult(RefundId: string.Empty, Success: false);
        }
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(EventType: eventType, Handled: true),
            "charge.failed" => new WebhookResult(EventType: eventType, Handled: true),
            "refund.created" => new WebhookResult(EventType: eventType, Handled: true),
            _ => new WebhookResult(EventType: eventType, Handled: false),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(string EventType, bool Handled);

