using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;
    private readonly FakePaymentProvider _provider;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    // ── Constructor ──────────────────────────────────────────────────

    [TestMethod]
    public void Ctor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    // ── ChargeAsync – validation ─────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null token")]
    [DataRow("", DisplayName = "empty token")]
    [DataRow("   ", DisplayName = "whitespace token")]
    public async Task ChargeAsync_InvalidToken_Throws(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "zero")]
    [DataRow(-5, DisplayName = "negative")]
    public async Task ChargeAsync_NonPositiveAmount_Throws(int amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", amount));
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMaximum_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
    }

    // ── ChargeAsync – success path ───────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccess()
    {
        _provider.NextChargeId = "ch_123";

        var result = await _gateway.ChargeAsync("tok_valid", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_123", result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "minimum")]
    [DataRow(999_999.99, DisplayName = "maximum")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        _provider.NextChargeId = "ch_boundary";

        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    // ── ChargeAsync – failure path ───────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ReturnsFailure()
    {
        _provider.ShouldThrow = true;

        var result = await _gateway.ChargeAsync("tok_valid", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_Cancelled_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    // ── RefundAsync – validation ─────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null chargeId")]
    [DataRow("", DisplayName = "empty chargeId")]
    [DataRow("  ", DisplayName = "whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_Throws(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    // ── RefundAsync – success path ───────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        _provider.NextRefundId = "re_456";

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("re_456", result.RefundId);
    }

    // ── RefundAsync – failure path ───────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ReturnsFailure()
    {
        _provider.ShouldThrow = true;

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_Cancelled_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync("ch_123", cts.Token));
    }

    // ── ProcessWebhook – validation ──────────────────────────────────

    [TestMethod]
    public void ProcessWebhook_NullEventType_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_NullPayload_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", null!));
    }

    // ── ProcessWebhook – known events ────────────────────────────────

    [TestMethod]
